        var limits=Row();var downStack=new StackPanel();downStack.Children.Add(Text("↓ "+L("Скачивание")+" · "+L("Мбит/с"),13,TrafficGraph.Mint));downInput=Input(store.Value.DownLimit.ToString(I18n.Culture),230);downStack.Children.Add(downInput);limits.Children.Add(downStack);var upStack=new StackPanel();upStack.Children.Add(Text("↑ "+L("Отдача")+" · "+L("Мбит/с"),13,TrafficGraph.Purple));upInput=Input(store.Value.UpLimit.ToString(I18n.Culture),230);upStack.Children.Add(upInput);limits.Children.Add(upStack);load.Children.Add(limits);
        maximum.Checked+=(_,_)=>RefreshEnabled();maximum.Unchecked+=(_,_)=>RefreshEnabled();downloadEnabled.Checked+=(_,_)=>RefreshEnabled();downloadEnabled.Unchecked+=(_,_)=>RefreshEnabled();uploadEnabled.Checked+=(_,_)=>RefreshEnabled();uploadEnabled.Unchecked+=(_,_)=>RefreshEnabled();
        var control=Row();control.Children.Add(Text(L("Длительность теста"),13));durationBox=Combo(new[]{L("5 мин"),L("15 мин"),L("1 час"),L("∞ Без лимита")},Array.IndexOf(new[]{5,15,60,0},store.Value.Duration));if(durationBox.SelectedIndex<0)durationBox.SelectedIndex=1;control.Children.Add(durationBox);start=Button(L("Начать тест"),()=>_=Toggle());start.Background=TrafficGraph.Mint;start.Foreground=Brushes.Black;control.Children.Add(start);load.Children.Add(control);load.Children.Add(Text(L("Лимит общий для всех потоков направления. На коротких интервалах возможны всплески."),12,Brushes.Gray));warning=Text("",13,Brushes.Orange);load.Children.Add(warning);
