        var daily=Panel(L("Интернет-трафик по дням"));var dailyActions=Row();unitBox=Combo(new[]{L("MB"),L("GB"),L("TB")},Array.IndexOf(new[]{"MB","GB","TB"},store.Value.Unit));unitBox.SelectionChanged+=(_,_)=>{store.Value.Unit=new[]{"MB","GB","TB"}[unitBox.SelectedIndex];Save();RenderHistory();};dailyActions.Children.Add(unitBox);dailyActions.Children.Add(Button(L("Сбросить историю"),()=>{if(MessageBox.Show(this,L("Суммы за все дни будут удалены. Текущий тест продолжится, новый трафик начнёт учитываться с нуля."),L("Сбросить историю трафика?"),MessageBoxButton.OKCancel,MessageBoxImage.Question)==MessageBoxResult.OK){if(engine.Running)Tick();store.Value.History.Clear();Save();RenderHistory();}}));daily.Children.Add(dailyActions);history=new();daily.Children.Add(history);daily.Children.Add(Text(L("Учитывается трафик тестов InternetPulse. История сохраняется между запусками. 1 ТБ = 1000 ГБ; 1 ГБ = 1000 МБ."),12,Brushes.Gray));
        var serverPanel=Panel(L("Тестовый сервер"));var filter=Row();countryBox=Combo(new[]{L("Все страны"),L("Россия"),L("Великобритания"),L("США"),L("Франция"),L("Германия"),L("Испания")});search=Input("",300);search.FontSize=14;search.ToolTip=L("Поиск серверов");filter.Children.Add(countryBox);filter.Children.Add(search);serverPanel.Children.Add(filter);serverBox=Combo([]);serverBox.MinWidth=780;serverPanel.Children.Add(serverBox);
        serverPanel.Children.Add(Text(L("Скачивание · HTTP GET"),12));downUrl=Input(store.Value.DownloadUrl,780);downUrl.FontSize=13;serverPanel.Children.Add(downUrl);serverPanel.Children.Add(Text(L("Отдача · HTTP PUT"),12));upUrl=Input(store.Value.UploadUrl,780);upUrl.FontSize=13;serverPanel.Children.Add(upUrl);serverPanel.Children.Add(Button(L("О сервере ↗"),()=>{if(serverBox.SelectedItem is ComboBoxItem item&&item.Tag is Server s)Open(s.source);}));serverPanel.Children.Add(Text(L("Для серверов «только скачивание» отдача отключается. Доступность и скорость зависят от сервера и сети. Для отдачи нужен HTTP PUT. Задержка — время до первого ответа с установкой соединения."),12,Brushes.Gray));
        countryBox.SelectionChanged+=(_,_)=>FillServers();search.TextChanged+=(_,_)=>FillServers();serverBox.SelectionChanged+=(_,_)=>{if(serverBox.SelectedItem is ComboBoxItem item&&item.Tag is Server s){downUrl.Text=s.download;upUrl.Text=s.upload??"";uploadEnabled.IsChecked=s.upload!=null;}};FillServers();
        var log=Panel(L("Журнал"));logText=Text("",12,Brushes.Gray);log.Children.Add(logText);root.Children.Add(Text(L("Тест создаёт реальный интернет-трафик. Скачанные файлы не сохраняются; для отдачи используются случайные байты. График и CSV — за последние 24 часа текущего запуска. Суммы по дням сохраняются между запусками."),12,Brushes.Gray));
        var footer=Row();footer.Children.Add(Text("Internet Pulse · "+L("Версия {0}","1.7.0"),12,Brushes.Gray));languageBox=Combo(I18n.Languages.Select(x=>x.Name),Array.FindIndex(I18n.Languages,x=>x.Code==I18n.Code));languageBox.SelectionChanged+=(_,_)=>{I18n.Code=I18n.Languages[languageBox.SelectedIndex].Code;store.Value.Language=I18n.Code;Save();Build();};footer.Children.Add(languageBox);footer.Children.Add(Button(L("Что нового"),WhatsNew));footer.Children.Add(Button(L("Проверить обновления"),()=>_=CheckUpdates()));root.Children.Add(footer);
