    void FillServers(){if(serverBox==null||downUrl==null)return;string current=downUrl.Text;serverBox.Items.Clear();string country=new[]{"all","RU","GB","US","FR","DE","ES"}[Math.Max(0,countryBox.SelectedIndex)];foreach(var s in servers.Where(s=>s.download==current||((country=="all"||s.country==country)&&(string.IsNullOrWhiteSpace(search.Text)||s.Label.Contains(search.Text,StringComparison.CurrentCultureIgnoreCase))))){var item=new ComboBoxItem{Content=s.Label,Tag=s};serverBox.Items.Add(item);if(s.download==current)serverBox.SelectedItem=item;}serverBox.Items.Add(new ComboBoxItem{Content=L("Свой сервер")});}
    void RefreshEnabled(){if(downInput==null||languageBox==null)return;bool idle=!engine.Running&&!stopping;foreach(var c in new Control[]{maximum,downloadEnabled,uploadEnabled,streamsBox,durationBox,serverBox,countryBox,search,downUrl,upUrl,languageBox})c.IsEnabled=idle;downInput.IsEnabled=idle&&maximum.IsChecked!=true&&downloadEnabled.IsChecked==true;upInput.IsEnabled=idle&&maximum.IsChecked!=true&&uploadEnabled.IsChecked==true;start.IsEnabled=!stopping;start.Content=L(stopping?"Остановка…":engine.Running?"Остановить":"Начать тест");export.IsEnabled=samples.Count>0;}
    async Task Toggle(){if(engine.Running){await Stop();return;}try{double d=downloadEnabled.IsChecked==true?(maximum.IsChecked==true?1:DownLimit):0,u=uploadEnabled.IsChecked==true?(maximum.IsChecked==true?1:UpLimit):0;engine.Start(downUrl.Text,upUrl.Text,d,u,int.Parse((string)streamsBox.SelectedItem),maximum.IsChecked==true);samples.Clear();events.Clear();previousDown=previousUp=0;previousTime=peakDown=peakUp=0;idleSeconds=ticks=0;elapsed.Restart();CaptureSettings();Save();timer.Start();SetThreadExecutionState(0x80000001);warning.Text="";RefreshEnabled();}catch(ArgumentException){MessageBox.Show(this,L("Укажите от 0,1 до 20000 Мбит/с и включите направление.")+"\n"+L("Проверьте адрес сервера: нужен HTTP или HTTPS URL без логина и пароля."));}}
    void CaptureSettings(){var s=store.Value;s.DownLimit=DownLimit>=0?DownLimit:s.DownLimit;s.UpLimit=UpLimit>=0?UpLimit:s.UpLimit;s.DownloadUrl=downUrl.Text;s.UploadUrl=upUrl.Text;s.Streams=int.Parse((string)streamsBox.SelectedItem);s.Duration=new[]{5,15,60,0}[durationBox.SelectedIndex];s.Maximum=maximum.IsChecked==true;s.DownloadEnabled=downloadEnabled.IsChecked==true;s.UploadEnabled=uploadEnabled.IsChecked==true;}
    void Tick(){if(!engine.Running&&!stopping)return;double now=elapsed.Elapsed.TotalSeconds,interval=Math.Max(.01,now-previousTime);long d=engine.Downloaded,u=engine.Uploaded;var sample=new Sample(DateTimeOffset.Now,(d-previousDown)*8/1e6/interval,(u-previousUp)*8/1e6/interval,d,u,engine.Latency,engine.Errors);store.Record(d-previousDown,u-previousUp,sample.Time);idleSeconds=d==previousDown&&u==previousUp?idleSeconds+1:0;previousDown=d;previousUp=u;previousTime=now;if(interval>=.75){peakDown=Math.Max(peakDown,sample.Down);peakUp=Math.Max(peakUp,sample.Up);}samples.Add(sample);if(samples.Count>86400)samples.RemoveRange(0,samples.Count-86400);if(++ticks%10==0)Save();if(engine.LastError!=""&&(events.Count==0||!events[0].EndsWith(engine.LastError))){events.Insert(0,DateTime.Now.ToString("T",I18n.Culture)+" · "+engine.LastError);if(events.Count>100)events.RemoveAt(events.Count-1);}RenderStats();RenderHistory();}
    void RenderStats(){var latest=samples.LastOrDefault();downSpeed.Text=I18n.Speed(engine.Running?latest?.Down??0:0)+" "+L("Мбит/с");upSpeed.Text=I18n.Speed(engine.Running?latest?.Up??0:0)+" "+L("Мбит/с");downTotal.Text=L("За этот тест")+" · "+I18n.Bytes(previousDown);upTotal.Text=L("За этот тест")+" · "+I18n.Bytes(previousUp);status.Text=L(stopping?"Остановка":engine.Running?(idleSeconds>=5?"Нет передачи данных":"Тест идёт"):"Готов к тесту");if(engine.Running){var remaining=store.Value.Duration==0?elapsed.Elapsed:TimeSpan.FromSeconds(Math.Max(0,store.Value.Duration*60-elapsed.Elapsed.TotalSeconds));status.Text+=" · "+(store.Value.Duration==0?L("ВРЕМЯ ТЕСТА"):L("ОСТАЛОСЬ"))+" "+remaining.ToString(@"hh\:mm\:ss");}warning.Text=engine.Running&&idleSeconds>=5?L("Сервер не передаёт данные. Проверьте журнал или выберите другой сервер."):"";peaks.Text=L("Рекорды сессии")+$" · ↓ {I18n.Speed(peakDown)} · ↑ {I18n.Speed(peakUp)} "+L("Мбит/с")+" · "+L("Максимум секундных замеров");timing.Text=L("Время теста  {0}",elapsed.Elapsed.ToString(@"hh\:mm\:ss"));diagnostics.Text=L("HTTP-задержка")+" · "+(engine.Latency<0?"—":engine.Latency.ToString("N0",I18n.Culture)+" "+L("мс"))+"     "+L("Ошибок соединения")+" · "+engine.Errors;logText.Text=events.Count==0?L("Здесь появятся запуск, остановка и ошибки соединения."):string.Join("\n",events.Take(5));graph.InvalidateVisual();export.IsEnabled=samples.Count>0;}
    void RenderHistory(){history.Children.Clear();var headings=new Grid();headings.ColumnDefinitions.Add(new());headings.ColumnDefinitions.Add(new(){Width=new GridLength(220)});headings.ColumnDefinitions.Add(new(){Width=new GridLength(220)});string[] labels=[L("День"),L("Скачано"),L("Отдано")];for(int i=0;i<3;i++){var h=Text(labels[i],12,i==1?TrafficGraph.Mint:i==2?TrafficGraph.Purple:Brushes.Gray);if(i>0)h.TextAlignment=TextAlignment.Right;Grid.SetColumn(h,i);headings.Children.Add(h);}history.Children.Add(headings);foreach(var day in store.Value.History.OrderByDescending(x=>x.Day).Take(31)){var grid=new Grid{Margin=new Thickness(0,7,0,7)};grid.ColumnDefinitions.Add(new());grid.ColumnDefinitions.Add(new(){Width=new GridLength(220)});grid.ColumnDefinitions.Add(new(){Width=new GridLength(220)});string[] values=[DateTime.ParseExact(day.Day,"yyyy-MM-dd",System.Globalization.CultureInfo.InvariantCulture).ToString("d MMMM yyyy",I18n.Culture),I18n.Amount(day.Downloaded,store.Value.Unit),I18n.Amount(day.Uploaded,store.Value.Unit)];for(int i=0;i<3;i++){var value=Text(values[i]);if(i>0)value.TextAlignment=TextAlignment.Right;Grid.SetColumn(value,i);grid.Children.Add(value);}history.Children.Add(grid);}if(store.Value.History.Count==0)history.Children.Add(Text(L("Запустите тест — здесь появится расход трафика за каждый день."),13,Brushes.Gray));}
    async Task Stop(bool completed=false){if(stopping||!engine.Running)return;stopping=true;RefreshEnabled();timer.Stop();await engine.Stop();Tick();elapsed.Stop();SetThreadExecutionState(0x80000000);stopping=false;events.Insert(0,DateTime.Now.ToString("T",I18n.Culture)+" · "+(completed?(engine.Errors==0?L("Тест успешно завершён"):L("Тест завершён с ошибками: {0}",engine.Errors.ToString())):L("Тест остановлен пользователем")));Save();RefreshEnabled();RenderStats();}
    void Save(){try{store.Save();}catch(IOException ex){if(warning!=null)warning.Text=L("Не удалось сохранить данные: {0}",ex.Message);}catch(UnauthorizedAccessException ex){if(warning!=null)warning.Text=L("Не удалось сохранить данные: {0}",ex.Message);}}
    void Export(){var dialog=new SaveFileDialog{Filter="CSV (*.csv)|*.csv",FileName="InternetPulse-"+DateTime.Now.ToString("yyyy-MM-dd-HHmmss")+".csv"};if(dialog.ShowDialog(this)!=true)return;var b=new StringBuilder("time,download_mbps,upload_mbps,download_bytes,upload_bytes,http_ttfb_ms,errors\n");foreach(var s in samples)b.AppendLine(FormattableString.Invariant($"{s.Time:O},{s.Down:F4},{s.Up:F4},{s.Downloaded},{s.Uploaded},{s.Latency:F4},{s.Errors}"));try{File.WriteAllText(dialog.FileName,b.ToString(),new UTF8Encoding(false));}catch(IOException ex){MessageBox.Show(this,L("Не удалось сохранить CSV: {0}",ex.Message));}}
    void WhatsNew(){var releases=JsonSerializer.Deserialize<ReleaseEntry[]>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"Resources","ReleaseHistory.json")))!;var body=new StackPanel{Margin=new Thickness(26)};foreach(var r in releases){body.Children.Add(Text(r.version+" · "+r.date,20,TrafficGraph.Mint));body.Children.Add(Text(L(r.title),17));foreach(var change in r.changes)body.Children.Add(Text("• "+L(change),14));body.Children.Add(Text(" "));}var window=new Window{Title=L("Что нового"),Owner=this,Width=640,Height=660,Background=BackgroundColor,Foreground=Brushes.White,Content=new ScrollViewer{Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto},WindowStartupLocation=WindowStartupLocation.CenterOwner};window.ShowDialog();}
    bool checking;async Task CheckUpdates(){if(checking)return;checking=true;try{using var client=new HttpClient(new SocketsHttpHandler{AllowAutoRedirect=false,UseCookies=false}){Timeout=TimeSpan.FromSeconds(15)};client.DefaultRequestHeaders.UserAgent.ParseAdd("InternetPulse/1.7.0");client.DefaultRequestHeaders.Accept.ParseAdd("application/vnd.github+json");using var response=await client.GetAsync("https://api.github.com/repos/Ezhov777/InternetPulse/releases/latest");if(response.StatusCode==System.Net.HttpStatusCode.NotFound){MessageBox.Show(this,L("Релизов пока нет"));return;}response.EnsureSuccessStatusCode();using var json=JsonDocument.Parse(await response.Content.ReadAsStringAsync());var tag=json.RootElement.GetProperty("tag_name").GetString()!;if(json.RootElement.GetProperty("draft").GetBoolean()||json.RootElement.GetProperty("prerelease").GetBoolean()){MessageBox.Show(this,L("Релизов пока нет"));return;}if(!Version.TryParse(tag.TrimStart('v','V').Split('+')[0],out var latest))throw new HttpRequestException("Invalid version");if(latest>new Version(1,7,0)){if(MessageBox.Show(this,L("Доступна версия {0}",tag)+"\n"+L("Новая версия доступна на GitHub. Откройте страницу релиза, чтобы посмотреть изменения и скачать приложение."),"Internet Pulse",MessageBoxButton.OKCancel)==MessageBoxResult.OK)Open("https://github.com/Ezhov777/InternetPulse/releases/latest");}else MessageBox.Show(this,L(latest==new Version(1,7,0)?"У вас установлена актуальная версия.":"Ваша версия новее последнего опубликованного релиза."));}catch(Exception ex)when(ex is HttpRequestException or TaskCanceledException or JsonException){MessageBox.Show(this,L("Не удалось проверить обновления. Попробуйте позже."));}finally{checking=false;}}
    static void Open(string url){if(Uri.TryCreate(url,UriKind.Absolute,out var uri)&&uri.Scheme=="https")Process.Start(new ProcessStartInfo(url){UseShellExecute=true});}
    async void ClosingWindow(object? sender,CancelEventArgs e){if(closeReady)return;e.Cancel=true;if(stopping)return;await Stop();CaptureSettings();Save();engine.Dispose();closeReady=true;Close();}
    [DllImport("kernel32.dll")]static extern uint SetThreadExecutionState(uint flags);
}
public static class Program {
    [STAThread]public static void Main(string[] args){var app=new Application();var window=new MainWindow();if(args.Contains("--smoke-test")){window.Show();var timer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(2)};timer.Tick+=(_,_)=>{timer.Stop();window.Close();};timer.Start();app.Run();}else app.Run(window);}
}
